"(o painel sem cadeado continua funcionando). Use isto se o certificado venceu, se o IP da TV mudou ou se um aparelho se perdeu.":"(ताले के बिना पैनल चलता रहता है)। इसे तब इस्तेमाल करें जब सर्टिफ़िकेट की अवधि खत्म हो गई हो, TV का IP बदल गया हो या किसी डिवाइस से खो गया हो।",
