"A TV":"TV",
"A TV ainda está gerando o certificado. Volte em 1 minuto.":"TV अभी सर्टिफ़िकेट बना रहा है। 1 मिनट बाद आएँ।",
"A TV ainda não deu acesso às sessões de mídia (o shell do launcher precisa estar de pé).":"TV के पास अभी मीडिया सेशन का एक्सेस नहीं है (लॉन्चर का shell चालू होना चाहिए)।",
"A TV avisa no celular: lembrete de jogo, alarme perdido, TV ligada de madrugada, erro, pedido de ajuda. Funciona com o painel aberto pelo endereço https (Tailscale, porta 8443) e o Chrome do Android. O aviso sai cifrado da TV.":"TV आपके फ़ोन पर सूचना भेजता है: मैच की याद, छूटा अलार्म, देर रात चालू TV, गड़बड़ी, मदद का अनुरोध। Android के Chrome में https पते (Tailscale, पोर्ट 8443) पर खुले पैनल से काम करता है। सूचना TV से एन्क्रिप्ट होकर जाती है।",
"A TV desliga e liga de novo (cerca de 1 min). O painel volta sozinho depois.":"TV बंद होकर फिर चालू होता है (लगभग 1 मिनट)। पैनल अपने आप लौट आता है।",
"A TV entra na sua rede Tailscale e publica só o MCP na internet.":"TV आपके Tailscale नेटवर्क में जुड़ता है और इंटरनेट पर सिर्फ़ MCP प्रकाशित करता है।",
"A TV está sem conta Google (ou o launcher está sem a permissão de ver as contas).":"TV पर कोई Google खाता नहीं है (या लॉन्चर खाते नहीं देख पाता)।",
"A TV fala direto com o Home Assistant da casa (sem nuvem): luzes e cenas aqui, na TV (Extras > Casa) e pelo Claude. Ela também aparece lá como sensor (ligada/dormindo, app aberto). O token fica cifrado na TV. Configurar pede o PIN.":"TV सीधे आपके Home Assistant से बात करता है (बिना क्लाउड): लाइटें और सीन यहाँ, TV पर (एक्स्ट्रा > घर) और Claude से। वहाँ यह सेंसर के रूप में भी दिखता है (चालू/सोया हुआ, खुला ऐप)। टोकन TV पर एन्क्रिप्ट रहता है। सेटअप PIN माँगता है।",
"A TV guarda sozinha uma cópia por dia (as últimas 7), só quando algo mudou. Baixe uma para restaurar em outra TV, ou volte esta TV para o estado daquele dia.":"TV खुद रोज़ एक कॉपी रखता है (आख़िरी 7), सिर्फ़ जब कुछ बदला हो। किसी दूसरे TV पर रीस्टोर करने के लिए एक डाउनलोड करें, या इस TV को उस दिन पर लौटाएँ।",
"A TV ligou":"TV चालू हुआ",
"A TV manda cada linha nova das origens marcadas (POST com JSON) para este endereço: https, ou http só dentro de casa (ex.: um webhook do Home Assistant). Mudar pede o PIN. Vazio desliga.":"TV चिह्नित स्रोतों की हर नई लाइन (JSON के साथ POST) इस पते पर भेजता है: https, या http सिर्फ़ घर के अंदर (जैसे Home Assistant webhook)। बदलने पर PIN माँगा जाता है। खाली छोड़ने से बंद।",
"A TV não criou a chave dos avisos. Tente de novo.":"TV ने सूचना कुंजी नहीं बनाई। फिर कोशिश करें।",
"A TV não está no Wi-Fi (no cabo ou desconectada): nada a ajustar no Wi-Fi.":"TV Wi-Fi पर नहीं है (केबल या डिस्कनेक्ट): Wi-Fi में कुछ बदलने को नहीं।",
"A TV passa a responder pela internet (Tailscale Funnel). Quem entrar precisa do PIN.":"TV इंटरनेट पर जवाब देना शुरू करता है (Tailscale Funnel)। साइन इन करने वाले को PIN चाहिए।",
"A TV sai da rede Tailscale. Para voltar, cole uma chave nova.":"TV Tailscale नेटवर्क छोड़ता है। वापस आने के लिए नई कुंजी पेस्ट करें।",
"A TV só digita letras, números, espaço e . , @ _ -":"TV सिर्फ़ अक्षर, अंक, स्पेस और . , @ _ - टाइप करता है",
"A TV vai":"TV करेगा:",
"A TV vai chamar":"TV कॉल करेगा:",
"A conexão com a TV caiu no meio do envio (rede, ou a TV recusou o arquivo).":"अपलोड के दौरान TV से कनेक्शन टूट गया (नेटवर्क, या TV ने फ़ाइल अस्वीकार की)।",
"A foto da tela não chegou inteira. Tentando de novo…":"स्क्रीनशॉट पूरा नहीं आया। फिर कोशिश कर रहे हैं…",
"A imagem da bolinha do perfil, no alto da tela da TV. Escolha qualquer foto: a TV recorta um quadrado do meio e guarda só nela. JPG, PNG ou WebP, até 8 MB.":"TV स्क्रीन के ऊपर दिखने वाली प्रोफ़ाइल फ़ोटो। कोई भी फ़ोटो चुनें: TV बीच से एक वर्ग काटता है और उसे सिर्फ़ TV पर रखता है। JPG, PNG या WebP, 8 MB तक।",
"A leitura está desligada.":"पढ़ना बंद है।",
"A semana ainda não foi montada (domingo, 20h).":"हफ़्ता अभी तैयार नहीं हुआ (रविवार, रात 8 बजे)।",
"A tela da TV está apagada: o recado aparece quando ela ligar.":"TV की स्क्रीन बंद है: स्क्रीन चालू होने पर संदेश दिखेगा।",
"Abra o painel pelo endereço de sempre (o IP da TV ou tv:8080).":"पैनल को हमेशा वाले पते पर खोलें (TV का IP या tv:8080)।",
