"Apaga login, configurações e downloads do app, como se tivesse acabado de instalar. Não tem volta.":"ऐप का साइन इन, सेटिंग्स और डाउनलोड मिटा देता है, जैसे अभी इंस्टॉल हुआ हो। वापस नहीं हो सकता।",
