"Apps abertos, baixados do GitHub oficial de cada projeto. Na 1ª instalação a TV guarda quem assinou; depois só aceita a mesma assinatura. Pede o PIN.":"ओपन-सोर्स ऐप, हर प्रोजेक्ट के आधिकारिक GitHub से डाउनलोड। पहली बार इंस्टॉल पर TV याद रखता है कि किसने साइन किया; उसके बाद सिर्फ़ वही सिग्नेचर मानता है। PIN माँगता है।",
"Apps da TV vão alcançar esses aparelhos pela rede Tailscale.":"TV के ऐप Tailscale नेटवर्क से इन डिवाइसों तक पहुँचेंगे।",
