"As próximas cópias saem trancadas com esta senha. Anote-a: sem ela não dá para restaurar.":"अगली कॉपियाँ इस पासवर्ड से बंद होंगी। लिखकर रखें: इसके बिना रीस्टोर नहीं हो सकता।",
