"Cada \"aparelho:porta\" vira http://127.0.0.1:porta na TV: no Jellyfin, Emby ou Kodi, use esse endereço como servidor. Só com a rede Tailscale ligada. Na mesma rede de casa não precisa.":"हर \"डिवाइस:पोर्ट\" TV पर http://127.0.0.1:पोर्ट बन जाता है: Jellyfin, Emby या Kodi में यही पता सर्वर के रूप में डालें। सिर्फ़ Tailscale नेटवर्क चालू होने पर। घर के उसी नेटवर्क पर ज़रूरत नहीं।",
"Cada evento roda no máximo uma vez a cada 20 s. Filmes de outros apps precisam do acesso às notificações (\"Tocando agora\").":"हर इवेंट 20 सेकंड में ज़्यादा से ज़्यादा एक बार चलता है। दूसरे ऐप की फ़िल्मों के लिए सूचनाओं का एक्सेस चाहिए (\"अभी चल रहा है\")।",
