"Claude (claude.ai, app do celular ou do PC)":"Claude (claude.ai, फ़ोन या PC ऐप)",
"Claude pela internet (MCP)":"इंटरनेट से Claude (MCP)",
"Claude, ChatGPT e outras IAs controlam a TV: controle remoto, abrir apps e links, instalar APK, despertadores, avisos, arquivos e shell. O que pede OK no controle segue as Confirmações. O login é este mesmo PIN, ou a conta Google, se ligada abaixo. O painel não fica na internet: só o MCP.":"Claude, ChatGPT और दूसरे AI TV को चलाते हैं: रिमोट, ऐप और लिंक खोलना, APK इंस्टॉल करना, अलार्म, संदेश, फ़ाइलें और shell। जिसमें रिमोट पर OK चाहिए, वह पुष्टियों के नियम मानता है। साइन इन यही PIN है, या नीचे चालू करें तो Google खाता। पैनल इंटरनेट पर नहीं है: सिर्फ़ MCP।",
"Cole a chave inteira (começa com tskey-).":"पूरी कुंजी पेस्ट करें (tskey- से शुरू होती है)।",
"Cole no arquivo de servidores MCP (mcp.json) e entre com o PIN quando pedir.":"MCP सर्वर वाली फ़ाइल (mcp.json) में पेस्ट करें और पूछे जाने पर PIN से साइन इन करें।",
"Com a chave \"Presença\" ligada: se os celulares marcados saírem da rede por 15 min e ninguém mexer no controle, a TV apaga a tela e avisa no celular.":"\"मौजूदगी\" स्विच चालू हो तो: अगर चुने गए फ़ोन 15 मिनट नेटवर्क से बाहर रहें और कोई रिमोट न छुए, TV स्क्रीन बंद करता है और फ़ोन पर सूचना देता है।",
"Com a chave ligada, um link secreto recebe recados (POST com JSON) do Home Assistant, dos Atalhos do iPhone ou de apps feitos para o TvOverlay. Gerar um link novo invalida o anterior e pede o PIN. O link só aparece agora: guarde-o.":"स्विच चालू होने पर एक गुप्त लिंक Home Assistant, iPhone शॉर्टकट या TvOverlay के ऐप से संदेश (JSON के साथ POST) लेता है। नया लिंक बनाने से पुराना बेकार हो जाता है और PIN माँगा जाता है। लिंक सिर्फ़ अभी दिखता है: सेव कर लें।",
"Com a chave ligada: no horário abaixo, só abrem os apps da lista (os do sistema sempre abrem) e o volume não passa do teto. Salvar pede o PIN.":"स्विच चालू होने पर: नीचे के समय में सिर्फ़ सूची वाले ऐप खुलते हैं (सिस्टम ऐप हमेशा खुलते हैं) और आवाज़ सीमा से ऊपर नहीं जाती। सेव करने पर PIN माँगा जाता है।",
"Com isto, o login do Claude (e dos outros apps) deixa de aceitar o PIN: só passa uma conta Google que esteja em algum perfil desta TV. Crie no Google Cloud um cliente OAuth do tipo \"TVs e dispositivos de entrada limitada\" e cole o id e o segredo aqui. Deixe o id vazio e salve para voltar ao PIN.":"इसके बाद Claude (और दूसरे ऐप) का साइन इन PIN नहीं मानता: सिर्फ़ वह Google खाता अंदर आता है जो इस TV की किसी प्रोफ़ाइल में है। Google Cloud में \"TV और सीमित इनपुट डिवाइस\" प्रकार का OAuth क्लाइंट बनाएँ और यहाँ id और सीक्रेट पेस्ट करें। PIN पर लौटने के लिए id खाली छोड़कर सेव करें।",
"Com o certificado que a TV fez instalado no aparelho, o painel abre com cadeado e vira app no celular e no PC.":"डिवाइस पर TV का सर्टिफ़िकेट इंस्टॉल हो तो पैनल ताले के साथ खुलता है और फ़ोन व PC पर ऐप बन जाता है।",
"Com o Fundo do protetor em “Fotos e vídeos passando” (na TV: Configurações › Tela e energia), o protetor mostra estas fotos por trás do relógio. Ficam só na TV, numa pasta do launcher. JPG, PNG ou WebP, até 15 MB cada.":"स्क्रीन सेवर की पृष्ठभूमि को “बदलती तस्वीरें और वीडियो” पर रखने पर (TV पर: सेटिंग्स › स्क्रीन और पावर), स्क्रीन सेवर ये फ़ोटो घड़ी के पीछे दिखाता है। ये सिर्फ़ TV पर, लॉन्चर के फ़ोल्डर में रहती हैं। JPG, PNG या WebP, हर एक 15 MB तक।",
