"Esquecer o Tailscale?":"Tailscale भूल जाएँ?",
"Esquecer o roteador (apaga endereço, chave e lista)":"राउटर भूल जाएँ (पता, कुंजी और सूची मिटाता है)",
"Esquecer o roteador?":"राउटर भूल जाएँ?",
"Esquerda":"बाएँ",
"Esse arquivo não é um backup válido (JSON).":"यह फ़ाइल मान्य बैकअप (JSON) नहीं है।",
"Esse é um backup completo: escreva a senha dele no campo abaixo e escolha o arquivo de novo.":"यह पूरा बैकअप है: नीचे के फ़ील्ड में उसका पासवर्ड लिखें और फ़ाइल फिर से चुनें।",
"Esta versão do launcher ainda não mostra o acesso remoto.":"लॉन्चर का यह वर्ज़न अभी रिमोट एक्सेस नहीं दिखाता।",
"Este app não entra em ações em lote (abra Detalhes)":"यह ऐप सामूहिक कार्रवाइयों में शामिल नहीं होता (विवरण खोलें)",
"Este app é protegido: o sistema ou o launcher dependem dele. As permissões aparecem só para consulta.":"यह ऐप सुरक्षित है: सिस्टम या लॉन्चर इस पर निर्भर है। अनुमतियाँ सिर्फ़ जानकारी के लिए दिखाई गई हैं।",
"Este navegador não recebe avisos por aqui. Abra o painel com cadeado (https, porta 8444) no Chrome do celular: veja Extras, \"Instalar como app\".":"यह ब्राउज़र यहाँ सूचनाएँ नहीं पाता। फ़ोन के Chrome में ताले वाला पैनल (https, पोर्ट 8444) खोलें: एक्स्ट्रा में \"ऐप के रूप में इंस्टॉल करें\" देखें।",
"Ex.: O jantar está pronto!":"जैसे: खाना तैयार है!",
"Falta a chave de API.":"API कुंजी नहीं है।",
