"Falta o endereço do roteador.":"राउटर का पता नहीं है।",
"Falta o endereço.":"पता नहीं है।",
"Fazendo o backup… (com cópia na rede pode levar até 1 min)":"बैकअप बन रहा है… (नेटवर्क कॉपी के साथ 1 मिनट तक लग सकता है)",
"Fazer agora":"अभी करें",
"Fazer o backup toda noite":"हर रात बैकअप लें",
"Fecha o app à força (como \"Forçar parada\"). Ele volta ao normal quando for aberto de novo.":"ऐप को ज़बरदस्ती बंद करता है (\"फ़ोर्स स्टॉप\" की तरह)। दोबारा खोलने पर सामान्य हो जाता है।",
"Fecha os apps em segundo plano (o da frente continua). Nada é apagado; o app fechado abre do zero.":"बैकग्राउंड के ऐप बंद करता है (सामने वाला रहता है)। कुछ नहीं मिटता; बंद हुआ ऐप शुरू से चलता है।",
"Fechar":"बंद करें",
"Feito: a TV sai do Wi-Fi e volta em alguns segundos. Depois, toque em Diagnosticar de novo.":"हो गया: TV Wi-Fi से हटता है और कुछ सेकंड में लौट आता है। फिर से जाँच करें दबाएँ।",
"Fica cifrada na TV. Depois, use \"Testar e recarregar canais\" para ver se ela funciona.":"यह TV पर एन्क्रिप्ट रहता है। फिर \"चैनल जाँचें और फिर लोड करें\" से देखें कि काम करता है या नहीं।",
