"O painel passa a abrir pelos aparelhos da sua conta Tailscale (ainda pede o PIN).":"पैनल अब आपके Tailscale खाते के डिवाइसों से खुलने लगता है (PIN फिर भी माँगता है)।",
"O primeiro mês aparece amanhã: a TV fecha um dia de cada vez.":"पहला महीना कल दिखेगा: TV एक-एक दिन बंद करता है।",
"O que a TV deve fazer":"TV को क्या करना है",
"O que dá para pedir":"आप क्या माँग सकते हैं",
"O que ele faz nesta TV agora":"अभी इस TV पर यह क्या करता है",
"O que mexeu na TV nos últimos 7 dias: painel, Claude, adb e a própria TV. O Claude lê o mesmo diário (ferramenta diario_tv).":"पिछले 7 दिनों में TV में किसने क्या बदला: पैनल, Claude, adb और खुद TV। Claude यही डायरी पढ़ता है (diario_tv टूल)।",
"O que o Android avisou":"Android ने क्या बताया",
"O roteador usa um certificado próprio. A TV só fala com ele depois de você conferir a impressão digital: abra https://<endereço do roteador> no computador, clique no cadeado e compare com a SHA-256 abaixo.":"राउटर अपना सर्टिफ़िकेट इस्तेमाल करता है। फ़िंगरप्रिंट जाँचने के बाद ही TV उससे बात करता है: कंप्यूटर पर https://<राउटर का पता> खोलें, ताले पर क्लिक करें और नीचे के SHA-256 से मिलाएँ।",
"O shell do launcher (teclas do painel, comandos do Claude, autocura) e o túnel do Claude pela internet às vezes param sem avisar. Aqui aparece se estão no ar, e o que a TV fez na manutenção da noite.":"लॉन्चर का shell (पैनल के बटन, Claude के कमांड, खुद ठीक होना) और Claude की इंटरनेट टनल कभी-कभी बिना बताए रुक जाते हैं। यहाँ दिखता है कि वे चल रहे हैं या नहीं, और रात के रखरखाव में TV ने क्या किया।",
"O shell do launcher não respondeu: sem a lista de memória e sem liberar (a depuração sem fio está ligada?).":"लॉन्चर के shell ने जवाब नहीं दिया: मेमोरी सूची नहीं और कुछ खाली नहीं हुआ (क्या वायरलेस डीबगिंग चालू है?)।",
"O vídeo terminou (2 min). Clique em \"Ver ao vivo\" para continuar.":"वीडियो खत्म हुआ (2 मिनट)। जारी रखने के लिए \"लाइव देखें\" पर क्लिक करें।",
"Esconder":"छिपाएँ",
"Ordem dos apps, tema, alarmes, DNS e as demais configurações do launcher, num arquivo JSON. O PIN não vai junto.":"ऐप का क्रम, थीम, अलार्म, DNS और लॉन्चर की बाकी सेटिंग्स, एक JSON फ़ाइल में। PIN साथ नहीं जाता।",
"Organizar":"व्यवस्थित करें",
"Os aparelhos que já instalaram o certificado atual vão parar de abrir o painel com cadeado até instalarem o novo":"जिन डिवाइसों में मौजूदा सर्टिफ़िकेट इंस्टॉल है, वे नया इंस्टॉल करने तक ताले के साथ पैनल नहीं खोल पाएँगे",
"Os canais dela somem do player da TV. Para voltar, é preciso cadastrar de novo.":"इसके चैनल TV के प्लेयर से गायब हो जाते हैं। वापस लाने के लिए इसे फिर जोड़ना होगा।",
"Os logins atuais são revogados: cada app entra de novo, agora com a conta Google.":"मौजूदा साइन इन रद्द होते हैं: हर ऐप फिर से साइन इन करता है, अब Google खाते से।",
"Ou a cidade, fora do Brasil (ex.: Lisboa)":"या ब्राज़ील के बाहर शहर (जैसे लिस्बन)",
"Outro app de IA":"दूसरा AI ऐप",
"Pacote enviado. O PC precisa estar no cabo e com Wake-on-LAN ligado.":"पैकेट भेजा गया। PC केबल से जुड़ा होना चाहिए और उसमें Wake-on-LAN चालू होना चाहिए।",
"Padrão":"डिफ़ॉल्ट",
"Padrão: de":"डिफ़ॉल्ट:",
"Painel":"पैनल",
"Palavras do Meu time":"मेरी टीम के शब्द",
"Palavras separadas por vírgula (\"Flamengo, Fórmula 1\"). Todo programa do guia com uma delas no título vira lembrete: a TV avisa 2 min antes. No guia em grade da TV, OK num programa futuro marca ou desmarca à mão.":"कॉमा से अलग शब्द (\"मुंबई इंडियंस, फ़ॉर्मूला 1\")। गाइड का हर कार्यक्रम जिसके शीर्षक में इनमें से कोई हो, रिमाइंडर बन जाता है: TV 2 मिनट पहले बताता है। TV की ग्रिड गाइड में किसी आने वाले कार्यक्रम पर OK उसे हाथ से चिह्नित या हटाता है।",
"Para mostrar de novo um app que estava escondido, digite o PIN.":"छिपे हुए ऐप को फिर दिखाने के लिए PIN डालें।",
"Para usar a foto da conta Google, abra na TV: Configurações do launcher > Conta > Buscar foto da conta.":"Google खाते की फ़ोटो इस्तेमाल करने के लिए TV पर खोलें: लॉन्चर सेटिंग्स > खाता > खाते की फ़ोटो लें।",
