"Por dia (vazio = segue o padrão acima; início igual ao fim = dia livre). O horário que passa da meia-noite vale para o dia em que começa: sexta 22:00 até 08:00 termina sábado às 8h.":"हर दिन (खाली = ऊपर का डिफ़ॉल्ट; शुरुआत और अंत बराबर = खुला दिन)। आधी रात पार करने वाला समय उस दिन का गिना जाता है जिस दिन शुरू होता है: शुक्रवार 22:00 से 08:00 शनिवार सुबह 8 बजे खत्म होता है।",
