"Subir uma pasta":"एक फ़ोल्डर ऊपर",
"Substitui as configurações da TV pelas do arquivo e reinicia o launcher. O estado de antes fica guardado:":"TV की सेटिंग्स को फ़ाइल की सेटिंग्स से बदलता है और लॉन्चर फिर शुरू करता है। पिछली स्थिति रखी जाती है:",
