"Símbolos que a TV não digita são pulados.":"जो चिह्न TV टाइप नहीं कर सकता, वे छोड़ दिए जाते हैं।",
"Só instale APK de fonte confiável: o app pode pedir permissões.":"सिर्फ़ भरोसेमंद स्रोतों से APK इंस्टॉल करें: ऐप अनुमतियाँ माँग सकता है।",
