"Toda noite, com a TV parada, ela guarda um backup completo trancado com a senha abaixo (ficam as 7 últimas cópias) e, se quiser, uma cópia extra no pendrive ou numa pasta da rede. Anote a senha: sem ela as cópias não abrem. Trocar a senha ou a cópia extra pede o PIN de novo.":"हर रात, TV खाली होने पर, यह नीचे के पासवर्ड से बंद पूरा बैकअप रखता है (आख़िरी 7 कॉपी रहती हैं) और, चाहें तो, पेन ड्राइव या नेटवर्क फ़ोल्डर में अतिरिक्त कॉपी। पासवर्ड लिख लें: उसके बिना कॉपी नहीं खुलतीं। पासवर्ड या अतिरिक्त कॉपी बदलने पर फिर PIN माँगा जाता है।",
"Todos os apps →":"सभी ऐप →",
"Todos saíram (presença)":"सब चले गए (मौजूदगी)",
"Token de longa duração":"लंबे समय का टोकन",
"Touchpad: arraste para mover, toque para OK":"टचपैड: खिसकाने के लिए खींचें, OK के लिए टैप करें",
"Travar \"Forçar parada\" e \"Limpar dados\" do launcher e da VPN":"लॉन्चर और VPN के \"फ़ोर्स स्टॉप\" और \"डेटा मिटाएँ\" लॉक करें",
"Trocar":"बदलें",
"Trocar a cópia extra?":"अतिरिक्त कॉपी बदलें?",
"Trocar foto…":"फ़ोटो बदलें…",
"Trocar o endereço apaga a chave e o certificado guardados (é preciso colar a chave de novo).":"पता बदलने से सेव की गई कुंजी और सर्टिफ़िकेट मिट जाते हैं (कुंजी फिर से पेस्ट करनी होगी)।",
"Tudo o que o backup acima leva e mais: contas de TV ao vivo, chave do UniFi, PIN do painel, controle parental, o Tailscale (a TV volta com o mesmo endereço) e os logins do Claude e dos outros apps no conector. Sai trancado com a senha abaixo: guarde-a, porque sem ela o arquivo não abre. Contas Google, Wi-Fi e logins de outros apps (Netflix, YouTube) o Android não deixa copiar.":"ऊपर के बैकअप में जो है वह सब और ज़्यादा: लाइव TV खाते, UniFi कुंजी, पैनल PIN, पैरेंटल कंट्रोल, Tailscale (TV उसी पते के साथ लौटता है) और कनेक्टर में Claude व दूसरे ऐप के साइन इन। यह नीचे के पासवर्ड से बंद होकर निकलता है: उसे रखें, उसके बिना फ़ाइल नहीं खुलती। Android Google खाते, Wi-Fi और दूसरे ऐप (Netflix, YouTube) के साइन इन कॉपी नहीं करने देता।",
"Um app que não está na lista volta do login por um domínio dele (o \"redirect\" que ele mostra, ex.: app.exemplo.com). Libere o domínio aqui, sem esperar versão nova da TV. Pede o PIN, e a TV ainda pergunta \"cliente novo?\" no primeiro login.":"सूची में न होने वाला ऐप साइन इन से अपने डोमेन के ज़रिए लौटता है (जो \"redirect\" वह दिखाता है, जैसे app.example.com)। TV के नए वर्ज़न का इंतज़ार किए बिना यहाँ डोमेन की अनुमति दें। PIN माँगता है, और पहले साइन इन पर TV फिर भी \"नया क्लाइंट?\" पूछता है।",
"Uma cena junta várias ações. Cada uma ganha um link secreto para os Atalhos do iPhone ou o Home Assistant (POST). O link só aparece ao criar: guarde-o. Criar e apagar pedem o PIN.":"सीन कई कार्रवाइयों को जोड़ता है। हर एक को iPhone शॉर्टकट या Home Assistant (POST) के लिए गुप्त लिंक मिलता है। लिंक सिर्फ़ बनाते समय दिखता है: सेव कर लें। बनाने और मिटाने पर PIN माँगा जाता है।",
"Usuário":"यूज़र",
"Vai só o tipo do erro e o ponto do código onde ele aconteceu. A mensagem do erro, a rede, as contas e os apps ficam na TV. O GitHub abre com o texto pronto e você revisa antes de enviar.":"सिर्फ़ त्रुटि का प्रकार और कोड में उसकी जगह जाती है। त्रुटि संदेश, नेटवर्क, खाते और ऐप TV पर रहते हैं। GitHub तैयार टेक्स्ट के साथ खुलता है और भेजने से पहले आप उसे देख लेते हैं।",
