"Addons":"ऐड-ऑन",
"Catálogos e vídeos de addons no formato do Stremio. Só vídeo por link direto (HTTP): torrent e P2P são recusados. Instalar e remover pedem o PIN.":"Stremio फ़ॉर्मैट वाले ऐड-ऑन से कैटलॉग और वीडियो। सिर्फ़ सीधे वीडियो लिंक (HTTP): torrent और P2P अस्वीकार। इंस्टॉल करने और हटाने पर PIN माँगा जाता है।",
"Li e aceito: quem instala responde pelo conteúdo do addon":"मैंने पढ़ा और स्वीकार करता हूँ: इंस्टॉल करने वाला ऐड-ऑन की सामग्री के लिए ज़िम्मेदार है",
"Endereço do addon":"ऐड-ऑन का पता",
"Nenhum addon instalado.":"कोई ऐड-ऑन इंस्टॉल नहीं।",
"Remover addon?":"ऐड-ऑन हटाएँ?",
"Instalar addon?":"ऐड-ऑन इंस्टॉल करें?",
"Remover":"हटाएँ",
"Este addon usa torrent/P2P. A TV só aceita addons com vídeo por link direto (HTTP).":"यह ऐड-ऑन torrent/P2P इस्तेमाल करता है। TV सिर्फ़ सीधे वीडियो लिंक (HTTP) वाले ऐड-ऑन स्वीकार करता है।",
"Addon marcado como conteúdo adulto: não é aceito.":"वयस्क सामग्री के रूप में चिह्नित ऐड-ऑन: स्वीकार नहीं।",
"Este addon precisa ser configurado antes. Configure no site dele e cole o endereço que ele der.":"इस ऐड-ऑन को पहले कॉन्फ़िगर करना होगा। इसकी वेबसाइट पर कॉन्फ़िगर करें और जो पता मिले उसे पेस्ट करें।",
"Este addon não oferece catálogo, ficha, vídeo ou legenda.":"यह ऐड-ऑन कैटलॉग, जानकारी, वीडियो या सबटाइटल नहीं देता।",
"O endereço não tem um addon válido (manifest.json).":"इस पते पर कोई मान्य ऐड-ऑन नहीं (manifest.json)।",
"Endereço inválido. Cole o link que termina em manifest.json.":"अमान्य पता। manifest.json पर खत्म होने वाला लिंक पेस्ट करें।",
"Limite de addons atingido. Remova um para instalar outro.":"ऐड-ऑन की सीमा पूरी। दूसरा इंस्टॉल करने के लिए एक हटाएँ।",
"O addon não respondeu. Confira o endereço e tente de novo.":"ऐड-ऑन ने जवाब नहीं दिया। पता जाँचें और फिर कोशिश करें।",
"Aceite os termos para instalar.":"इंस्टॉल करने के लिए शर्तें स्वीकार करें।",
"Addons são feitos por terceiros. A Sofaly não cria, não hospeda e não confere o que eles mostram. Quem instala um addon responde pelo conteúdo dele e por ter direito de assistir. A Sofaly só toca vídeo por link direto: fontes de torrent e P2P são ignoradas.":"ऐड-ऑन तीसरे पक्ष बनाते हैं। Sofaly उनमें दिखने वाली चीज़ें न बनाता है, न होस्ट करता है, न जाँचता है। ऐड-ऑन इंस्टॉल करने वाला उसकी सामग्री और उसे देखने का अधिकार होने के लिए ज़िम्मेदार है। Sofaly सिर्फ़ सीधे वीडियो लिंक चलाता है: torrent और P2P स्रोत अनदेखे किए जाते हैं।",
"Ler QR":"QR स्कैन करें",
"Fechar câmera":"कैमरा बंद करें",
"Câmera lendo o QR do addon":"ऐड-ऑन का QR पढ़ता कैमरा",
