"Não consegui abrir a câmera. Confira se o navegador tem permissão para usá-la.":"कैमरा नहीं खुल सका। जाँचें कि ब्राउज़र को इसे इस्तेमाल करने की अनुमति है।",
"QR lido. Confira o endereço e toque em Instalar.":"QR पढ़ लिया। पता जाँचें और इंस्टॉल करें दबाएँ।",
