"App grande: em pendrive lento a mudança pode passar de 10 minutos e já travou uma TV no meio. O app fecha enquanto é movido. Só continue com ninguém assistindo.":"बड़ा ऐप: धीमी पेन ड्राइव पर यह 10 मिनट से ज़्यादा ले सकता है और एक TV को बीच में अटका चुका है। ले जाते समय ऐप बंद रहता है। तभी जारी रखें जब कोई देख न रहा हो।",
"Não deu: este pendrive grava devagar demais (menos de 10 MB/s) para virar memória da TV. Use como pendrive comum.":"नहीं हुआ: यह पेन ड्राइव TV मेमोरी बनने के लिए बहुत धीरे लिखती है (10 MB/s से कम)। इसे सामान्य पेन ड्राइव की तरह इस्तेमाल करें।",
