"Ajuste de aparência ou de configuração de outro app ou do sistema, feito pelo fabricante. Não tem tela nem código próprio.":"निर्माता द्वारा किसी दूसरे ऐप या सिस्टम के रूप या सेटिंग का समायोजन। इसकी अपनी कोई स्क्रीन या कोड नहीं है।",
