"Este launcher: a tela inicial, o despertador, o protetor de tela e este painel. É o dono do aparelho (Device Owner).":"यह लॉन्चर: होम स्क्रीन, अलार्म, स्क्रीनसेवर और यह पैनल। यही डिवाइस का मालिक (Device Owner) है।",
"Sem ele a TV perde a tela inicial, o Device Owner e este painel. Desinstalar é irreversível sem reset de fábrica.":"इसके बिना TV होम स्क्रीन, Device Owner और यह पैनल खो देता है। अनइंस्टॉल करना फ़ैक्टरी रीसेट के बिना वापस नहीं होता।",
