"Filmes e séries da Amazon.":"Amazon की फ़िल्में और सीरीज़।",
"Só ele some.":"सिर्फ़ यही ऐप हटता है।",
"A tela de confirmar backup ou restauração pelo adb.":"adb से बैकअप या रीस्टोर की पुष्टि करने वाली स्क्रीन।",
