"Ajustes do Bluetooth do Chromecast: controle remoto, fones e caixas.":"Chromecast की ब्लूटूथ सेटिंग्स: रिमोट, हेडफ़ोन और स्पीकर।",
"O controle remoto e os fones Bluetooth podem parar.":"रिमोट और ब्लूटूथ हेडफ़ोन काम करना बंद कर सकते हैं।",
"Liga instrumentos musicais (MIDI) pelo Bluetooth.":"संगीत वाद्य (MIDI) ब्लूटूथ से जोड़ता है।",
"Nada para quem não liga teclado musical na TV.":"अगर आप TV से संगीत कीबोर्ड नहीं जोड़ते तो कुछ नहीं।",
"Extensões de câmera. A TV não tem câmera.":"कैमरा एक्सटेंशन। TV में कैमरा नहीं है।",
