"Protetores de tela básicos do Android (cores). Este launcher usa o protetor próprio.":"Android के बुनियादी स्क्रीनसेवर (रंग)। यह लॉन्चर अपना स्क्रीनसेवर इस्तेमाल करता है।",
"Nada: o protetor de tela é o do launcher.":"कुछ नहीं: स्क्रीनसेवर लॉन्चर का है।",
