"Dá acesso aos arquivos da memória interna e de pen drive para os outros apps.":"दूसरे ऐप्स को इंटरनल स्टोरेज और पेन ड्राइव की फ़ाइलों तक पहुँच देता है।",
"Apps de arquivos e de mídia deixam de ver pastas e pen drives.":"फ़ाइल और मीडिया ऐप्स फ़ोल्डर और पेन ड्राइव नहीं देख पाते।",
"Mostra páginas HTML simples, como as licenças nas Configurações.":"साधारण HTML पेज दिखाता है, जैसे सेटिंग्स में लाइसेंस।",
