"Um teclado físico pode digitar as letras erradas.":"फ़िज़िकल कीबोर्ड गलत अक्षर टाइप कर सकता है।",
"A tela \"Abrir com\", que aparece quando mais de um app pode abrir a mesma coisa.":"\"इसके साथ खोलें\" स्क्रीन, जो तब आती है जब एक ही चीज़ कई ऐप्स खोल सकते हैं।",
"Apps que perguntam com qual app abrir algo travam ou fecham.":"जो ऐप्स पूछते हैं कि किस ऐप से खोलें, वे अटक जाते हैं या बंद हो जाते हैं।",
"Guarda certificados e chaves do sistema (Wi-Fi, VPN, apps).":"सिस्टम के सर्टिफ़िकेट और कुंजियाँ रखता है (Wi-Fi, VPN, ऐप्स)।",
