"Baixar o app":"ऐप डाउनलोड करें",
"Agora não":"अभी नहीं",
"Ainda não. Depois de instalar, volte para esta página (ela confere a cada 3 segundos).":"अभी नहीं। इंस्टॉल करने के बाद इस पेज पर लौटें (यह हर 3 सेकंड में जाँचता है)।",
