"A TV não conseguiu fazer isso agora. Tente de novo em alguns segundos; se repetir, veja a aba Registro.":"टीवी अभी यह नहीं कर सका। कुछ सेकंड बाद फिर कोशिश करें; अगर दोहराए, तो लॉग टैब देखें।",
"A TV respondeu de um jeito que esta tela não esperava. Recarregue a página; se continuar, o launcher da TV e o painel podem estar em versões diferentes.":"टीवी ने ऐसा जवाब दिया जिसकी इस स्क्रीन को उम्मीद नहीं थी। पेज फिर से लोड करें; अगर जारी रहे, तो टीवी का लॉन्चर और पैनल अलग-अलग संस्करणों पर हो सकते हैं।",
